"use client";
import "./image-viewport.css";
import {
  useLayoutEffect,
  useRef,
  useState,
  type ReactNode,
  type CSSProperties,
} from "react";
import {
  FIT_IMAGE_VIEW,
  constrainImageView,
  zoomImageAt,
  type ImageFrame,
  type ImageView,
} from "./image-geometry";
type Point = { x: number; y: number };
import { createPositionMotion } from "./position-motion";
import { presentationSpring } from "./physical-spring";
export interface ImageViewportProps {
  active?: boolean;
  className?: string;
  style?: CSSProperties;
  label?: string;
  naturalWidth: number;
  naturalHeight: number;
  children: ReactNode;
}
/** Transforms stay outside React/document state; controls only receive the zoom readout. */
export function ImageViewport({
  active = true,
  naturalWidth,
  naturalHeight,
  children,
  className = "",
  style,
  label = "Image zoom and pan",
}: ImageViewportProps) {
  const root = useRef<HTMLDivElement>(null),
    activeRef = useRef(active);
  activeRef.current = active;
  const api = useRef<{
    zoom: (factor: number) => void;
    fit: () => void;
  } | null>(null);
  const [scale, setScale] = useState(1);
  useLayoutEffect(() => {
    const node = root.current!,
      image = node.querySelector("img");
    if (!image) return;
    const reduced = matchMedia("(prefers-reduced-motion: reduce)"),
      points = new Map<number, Point>();
    let frame: ImageFrame = {
      width: node.clientWidth,
      height: node.clientHeight,
      naturalWidth,
      naturalHeight,
    };
    let pan: { point: Point; view: ImageView } | null = null;
    let pinch: { middle: Point; distance: number; view: ImageView } | null =
      null;
    const motion = createPositionMotion(image, FIT_IMAGE_VIEW, (pose) => {
      image.style.transform = `translate3d(${pose.x}px, ${pose.y}px, 0) scale(${pose.scale})`;
      node.dataset.zoom = String(pose.scale);
      node.dataset.pannable = String(activeRef.current && pose.scale > 1.001);
    });
    const current = (): ImageView => {
      const pose = motion.read();
      return { x: pose.x, y: pose.y, scale: pose.scale };
    };
    const paint = (view: ImageView) => {
      const bounded = constrainImageView(view, frame);
      motion.set(bounded);
      setScale(bounded.scale);
    };
    const fit = () => {
      cancel();
      motion.to(FIT_IMAGE_VIEW, reduced.matches, {
        spring: presentationSpring(false),
        preserveVelocity: false,
      });
      setScale(1);
    };
    const anchor = (event: { clientX: number; clientY: number }): Point => {
      const rect = node.getBoundingClientRect();
      return {
        x:
          ((event.clientX - rect.left) * node.clientWidth) /
            Math.max(1, rect.width) -
          node.clientWidth / 2,
        y:
          ((event.clientY - rect.top) * node.clientHeight) /
            Math.max(1, rect.height) -
          node.clientHeight / 2,
      };
    };
    const zoom = (factor: number, point: Point = { x: 0, y: 0 }) => {
      cancel();
      const view = current();
      paint(zoomImageAt(view, point, view.scale * factor, frame));
    };
    api.current = { zoom, fit };
    const observer = new ResizeObserver(() => {
      frame = {
        width: node.clientWidth,
        height: node.clientHeight,
        naturalWidth,
        naturalHeight,
      };
      if (activeRef.current && !points.size) paint(current());
    });
    observer.observe(node);
    const down = (event: PointerEvent) => {
      if (
        !activeRef.current ||
        event.button !== 0 ||
        (event.target as Element).closest("button")
      )
        return;
      if (
        event.pointerType !== "touch" ||
        motion.peek().scale > 1.001 ||
        points.size
      )
        event.preventDefault();
      event.stopPropagation();
      node.focus({ preventScroll: true });
      points.set(event.pointerId, anchor(event));
      node.setPointerCapture(event.pointerId);
      if (points.size === 1) pan = { point: anchor(event), view: current() };
      if (points.size === 2) {
        const [a, b] = [...points.values()];
        pinch = {
          middle: { x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 },
          distance: Math.max(1, Math.hypot(a.x - b.x, a.y - b.y)),
          view: current(),
        };
      }
    };
    const move = (event: PointerEvent) => {
      if (!points.has(event.pointerId)) return;
      if (
        event.pointerType === "touch" &&
        points.size === 1 &&
        motion.peek().scale <= 1.001
      )
        return;
      event.preventDefault();
      event.stopPropagation();
      points.set(event.pointerId, anchor(event));
      if (points.size >= 2 && pinch) {
        const [a, b] = [...points.values()],
          middle = { x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 };
        const view = zoomImageAt(
          pinch.view,
          pinch.middle,
          (pinch.view.scale * Math.hypot(a.x - b.x, a.y - b.y)) /
            pinch.distance,
          frame,
        );
        paint({
          ...view,
          x: view.x + middle.x - pinch.middle.x,
          y: view.y + middle.y - pinch.middle.y,
        });
      } else if (pan) {
        const point = anchor(event);
        paint({
          ...pan.view,
          x: pan.view.x + point.x - pan.point.x,
          y: pan.view.y + point.y - pan.point.y,
        });
      }
    };
    const end = (event: PointerEvent) => {
      if (!points.delete(event.pointerId)) return;
      event.stopPropagation();
      if (node.hasPointerCapture(event.pointerId))
        node.releasePointerCapture(event.pointerId);
      pinch = null;
      pan = points.size
        ? { point: [...points.values()][0], view: current() }
        : null;
    };
    const wheel = (event: WheelEvent) => {
      if (!activeRef.current || !(event.ctrlKey || event.metaKey)) return;
      event.preventDefault();
      event.stopPropagation();
      zoom(
        Math.exp(
          -event.deltaY *
            (event.deltaMode === 1
              ? 16
              : event.deltaMode === 2
                ? frame.height
                : 1) *
            0.002,
        ),
        anchor(event),
      );
    };
    const double = (event: MouseEvent) => {
      if (!activeRef.current || (event.target as Element).closest("button"))
        return;
      event.preventDefault();
      event.stopPropagation();
      motion.peek().scale > 1.01 ? fit() : zoom(2, anchor(event));
    };
    const key = (event: KeyboardEvent) => {
      if (!activeRef.current || event.target !== node) return;
      if (
        [
          "+",
          "=",
          "-",
          "0",
          "ArrowLeft",
          "ArrowRight",
          "ArrowUp",
          "ArrowDown",
        ].includes(event.key)
      ) {
        event.preventDefault();
        event.stopPropagation();
        if (event.key === "0") fit();
        else if (["+", "=", "-"].includes(event.key))
          zoom(event.key === "-" ? 1 / 1.25 : 1.25);
        else {
          const view = current(),
            step = event.shiftKey ? 80 : 24;
          paint({
            ...view,
            x:
              view.x +
              (event.key === "ArrowLeft"
                ? step
                : event.key === "ArrowRight"
                  ? -step
                  : 0),
            y:
              view.y +
              (event.key === "ArrowUp"
                ? step
                : event.key === "ArrowDown"
                  ? -step
                  : 0),
          });
        }
      }
    };
    const cancel = () => {
      const ids = [...points.keys()];
      points.clear();
      pan = pinch = null;
      for (const id of ids)
        if (node.hasPointerCapture(id)) node.releasePointerCapture(id);
    };
    const preference = () => {
      if (reduced.matches) motion.finish();
    };
    const visibility = () => {
      if (document.hidden) {
        cancel();
        motion.finish();
      }
    };
    const abort = new AbortController(),
      opts = { signal: abort.signal };
    node.addEventListener("pointerdown", down, opts);
    node.addEventListener("pointermove", move, opts);
    node.addEventListener("pointerup", end, opts);
    node.addEventListener("pointercancel", end, opts);
    node.addEventListener("lostpointercapture", end, opts);
    node.addEventListener("wheel", wheel, { ...opts, passive: false });
    node.addEventListener("dblclick", double, opts);
    node.addEventListener("keydown", key, opts);
    window.addEventListener("blur", cancel, opts);
    document.addEventListener("visibilitychange", visibility, opts);
    reduced.addEventListener("change", preference, opts);
    return () => {
      cancel();
      abort.abort();
      observer.disconnect();
      motion.dispose();
      image.style.removeProperty("transform");
      api.current = null;
    };
  }, [naturalWidth, naturalHeight]);
  useLayoutEffect(() => {
    if (!active) api.current?.fit();
  }, [active]);
  return (
    <div
      ref={root}
      className={`roc-image-viewport ${className}`}
      style={style}
      tabIndex={active ? 0 : -1}
      aria-label={label}
      title={active ? "Scroll to read · Ctrl/⌘ + wheel to zoom" : undefined}
    >
      {children}
      <div
        className="roc-image-tools"
        hidden={!active}
        aria-label="Image view controls"
      >
        <button
          type="button"
          onClick={() => api.current?.zoom(1 / 1.25)}
          aria-label="Zoom image out"
          title="Zoom out (−)"
        >
          −
        </button>
        <button
          type="button"
          onClick={() => api.current?.fit()}
          aria-label="Fit image"
          title="Fit image (0)"
        >
          {Math.abs(scale - 1) < 0.001 ? "Fit" : `${Math.round(scale * 100)}%`}
        </button>
        <button
          type="button"
          onClick={() => api.current?.zoom(1.25)}
          aria-label="Zoom image in"
          title="Zoom in (+)"
        >
          +
        </button>
      </div>
    </div>
  );
}

@import "./surface.css";
.roc-image-viewport {
  position: relative;
  isolation: isolate;
  width: 100%;
  height: 300px;
  overflow: hidden;
  border-radius: var(--roc-radius, 10px);
  background: #e8ebe6;
  touch-action: pan-y;
}
.roc-image-viewport > img {
  width: 100%;
  height: 100%;
  object-fit: contain;
  display: block;
  transform-origin: center;
  user-select: none;
  pointer-events: none;
}
.roc-image-viewport[data-pannable="true"] {
  cursor: grab;
  touch-action: none;
}
.roc-image-viewport:active {
  cursor: grabbing;
}
.roc-image-tools {
  position: absolute;
  z-index: 1;
  bottom: 12px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  background: var(--roc-paper, #fcfbf8);
  border: 1px solid #ffffff80;
  border-radius: 24px;
  padding: 4px;
  gap: 3px;
  backdrop-filter: blur(12px);
}
.roc-image-tools button {
  border: 0;
  background: none;
  padding: 7px 11px;
  font: 12px system-ui;
  min-width: 36px;
}
.roc-image-tools[hidden] {
  display: none;
}

@import "./animation.css";
@import "./corners.css";
@import "./responsive.css";
/* Shared surface primitives only. Tokens inherit from the host. No page reset. */
:where(
  .roc-expand,
  .roc-folder,
  .roc-sources,
  .roc-lanes,
  .roc-tabs,
  .roc-card-preview,
  .roc-image-viewport,
  .roc-voice,
  .roc-selection-toolbar,
  .roc-page-book,
  .roc-source-tray
) {
  color: var(--roc-ink, #30332e);
  font-family: inherit;
  box-sizing: border-box;
}
:where(
    .roc-expand,
    .roc-folder,
    .roc-sources,
    .roc-lanes,
    .roc-tabs,
    .roc-card-preview,
    .roc-image-viewport,
    .roc-voice,
    .roc-selection-toolbar,
    .roc-page-book,
    .roc-source-tray
  )
  * {
  box-sizing: border-box;
}
:where(
    .roc-expand,
    .roc-folder,
    .roc-sources,
    .roc-lanes,
    .roc-tabs,
    .roc-card-preview,
    .roc-image-viewport,
    .roc-voice,
    .roc-selection-toolbar,
    .roc-page-book,
    .roc-source-tray
  )
  button {
  font: inherit;
  color: inherit;
  cursor: pointer;
}
.roc-image-viewport:focus-visible,
.roc-page-book:focus-visible,
:where(
    .roc-expand,
    .roc-folder,
    .roc-sources,
    .roc-lanes,
    .roc-tabs,
    .roc-card-preview,
    .roc-image-viewport,
    .roc-voice,
    .roc-selection-toolbar,
    .roc-page-book,
    .roc-source-tray
  )
  button:focus-visible {
  outline: none;
  box-shadow: inset 0 0 0 2px var(--roc-focus, #737373) !important;
}
@media (forced-colors: active) {
  .roc-image-viewport:focus-visible,
  .roc-page-book:focus-visible,
  :where(
      .roc-expand,
      .roc-folder,
      .roc-sources,
      .roc-lanes,
      .roc-tabs,
      .roc-card-preview,
      .roc-image-viewport,
      .roc-voice,
      .roc-selection-toolbar,
      .roc-page-book,
      .roc-source-tray
    )
    button:focus-visible {
    outline: 2px solid Highlight;
    outline-offset: -2px;
  }
}
.roc-eyebrow {
  font:
    10px/1.4 ui-monospace,
    monospace;
  letter-spacing: 0.12em;
  color: var(--roc-muted, #757b72);
}
.roc-text-button {
  border: 0;
  background: none;
  padding: 9px 0;
  font-size: 12px;
  text-align: left;
  display: inline-flex;
  gap: 20px;
  align-items: center;
}

/* ROC owns motion; Base UI owns interaction and portal presence. */
/* These parts use spring positions, so a CSS transition would lag the pointer. */
.roc-ui[data-slot="slider-thumb"],
.roc-ui[data-slot="slider-range"] {
  transition-property: background-color, border-color, box-shadow;
}
/* Static content stays still; interactive surfaces respond to state changes. */
:where(.roc-ui, .roc-shadcn):is(
  [data-slot="card"], [data-slot="item"], [data-slot="attachment"],
  [data-slot="table-row"], [data-slot="sidebar-menu-button"]
) {
  transition: background-color 150ms ease-out, border-color 150ms ease-out,
    box-shadow 150ms ease-out;
}
@media (prefers-reduced-motion: reduce) {
  :where(.roc-ui, .roc-shadcn):is(
    [data-slot="card"], [data-slot="item"], [data-slot="attachment"],
    [data-slot="table-row"], [data-slot="sidebar-menu-button"]
  ) { transition: none; }
}

/* Smooth squircle corners, following the visual treatment at https://corne.rs/.
   Native corner shaping keeps borders, shadows and overflowing content intact.
   Browsers without support retain the existing border-radius fallback. */
:where(
  [class^="roc-"],
  [class*=" roc-"],
  [class^="roc-"] *,
  [class*=" roc-"] *
) {
  /* ROC limits by role, informed by Apple's compact-control and surface guidance.
     These are ROC values, not platform-prescribed dimensions. Zero stays square. */
  --roc-radius-compact: min(var(--roc-radius, 9px), 8px);
  --roc-radius-control: min(var(--roc-radius, 9px), 10px);
  --roc-radius-popup: min(var(--roc-radius, 9px), 12px);
  --roc-radius-surface: min(var(--roc-radius, 12px), 20px);
}
@supports (corner-shape: squircle) {
  :where(
    [class^="roc-"],
    [class*=" roc-"],
    [class^="roc-"] *,
    [class*=" roc-"] *
  ) {
    corner-shape: var(--roc-corner-shape, squircle);
  }
}

/* Shared viewport constraints for portalled controls, including standalone consumers. */
:is(.roc-ui, .roc-shadcn)[data-slot]:is(
  [data-slot="popover-content"],
  [data-slot="hover-card-content"],
  [data-slot="tooltip-content"],
  [data-slot="select-content"],
  [data-slot="combobox-content"],
  [data-slot="dropdown-menu-content"],
  [data-slot="dropdown-menu-sub-content"],
  [data-slot="context-menu-content"],
  [data-slot="context-menu-sub-content"],
  [data-slot="menubar-content"],
  [data-slot="menubar-sub-content"]
) {
  max-inline-size: min(var(--available-width, calc(100vw - 24px)), calc(100vw - 24px));
  max-block-size: min(var(--available-height, calc(100dvh - 24px)), calc(100dvh - 24px));
  overflow: auto;
  overflow-wrap: anywhere;
  overscroll-behavior: contain;
}
@media (max-width: 640px), (pointer: coarse) {
  .roc-ui.roc-ui-button[data-slot],
  .roc-ui[data-slot="native-select"],
  .roc-shadcn[data-slot="select-trigger"] {
    min-height: 44px;
  }
  .roc-ui.roc-ui-button[data-size^="icon"] {
    width: 44px;
    height: 44px;
  }
  .roc-ui[data-slot="input"],
  .roc-ui[data-slot="textarea"],
  .roc-shadcn[data-slot="input-group-control"] {
    font-size: 16px;
  }
  .roc-ui[data-slot="input"],
  .roc-shadcn[data-slot="input-group"],
  .roc-ui[data-slot="slider"] {
    min-height: 44px;
  }
  .roc-shadcn[data-slot="input-group"] [data-slot="input-group-control"] {
    min-height: 42px;
  }
  .roc-sidebar-link,
  .roc-ui[data-slot="tabs-trigger"],
  .roc-ui[data-slot="toggle"],
  .roc-shadcn[data-slot="select-item"],
  .roc-shadcn[data-slot="combobox-item"] {
    min-height: 44px;
  }
  .roc-ui[data-slot="dropdown-menu-item"],
  .roc-ui[data-slot="dropdown-menu-checkbox-item"],
  .roc-ui[data-slot="dropdown-menu-radio-item"],
  .roc-shadcn[data-slot="context-menu-item"],
  .roc-shadcn[data-slot="menubar-item"] {
    min-height: 44px;
  }
}

// Extracted from Franklin Board React worktree; MIT. See SOURCE-LICENSE.txt.
type Point = { x: number; y: number };
export interface ImageView extends Point {
  scale: number;
}
export interface ImageFrame {
  width: number;
  height: number;
  naturalWidth: number;
  naturalHeight: number;
}
export const FIT_IMAGE_VIEW: ImageView = { x: 0, y: 0, scale: 1 };
export function constrainImageView(
  view: ImageView,
  frame: ImageFrame,
): ImageView {
  const scale = Math.max(
    1,
    Math.min(8, Number.isFinite(view.scale) ? view.scale : 1),
  );
  const fit = Math.min(
    frame.width / Math.max(1, frame.naturalWidth),
    frame.height / Math.max(1, frame.naturalHeight),
  );
  const x = Math.max(0, (frame.naturalWidth * fit * scale - frame.width) / 2);
  const y = Math.max(0, (frame.naturalHeight * fit * scale - frame.height) / 2);
  return {
    scale,
    x: Math.max(-x, Math.min(x, Number.isFinite(view.x) ? view.x : 0)),
    y: Math.max(-y, Math.min(y, Number.isFinite(view.y) ? view.y : 0)),
  };
}
/** Anchor is relative to the centre of the fitted viewport. */
export function zoomImageAt(
  view: ImageView,
  anchor: Point,
  scale: number,
  frame: ImageFrame,
): ImageView {
  const next = Math.max(1, Math.min(8, scale)),
    ratio = next / view.scale;
  return constrainImageView(
    {
      scale: next,
      x: anchor.x - (anchor.x - view.x) * ratio,
      y: anchor.y - (anchor.y - view.y) * ratio,
    },
    frame,
  );
}

// Extracted from Franklin Board React worktree; MIT. See SOURCE-LICENSE.txt.
import {
  DEFAULT_SPRING,
  sampleSpring,
  type SpringOptions,
} from "./physical-spring";
type Pose = { x: number; y: number; scale: number; rotation: number };
const poseOf = (p: { x: number; y: number }): Pose => ({
  ...p,
  scale: 1,
  rotation: 0,
});
type Point = { x: number; y: number };
export interface MotionOptions {
  spring?: SpringOptions;
  preserveVelocity?: boolean;
  progressVelocity?: number;
  onFinish?: () => void;
}
export interface GeometryPose extends Pose {
  width: number;
  height: number;
}
const keys = ["x", "y", "scale", "rotation", "width", "height"] as const;
/** One transform writer per retained shell. Optional painter also drives camera/lid. */
export function createPositionMotion(
  node: HTMLElement,
  initial: Point & Partial<GeometryPose>,
  painter?: (pose: GeometryPose) => void,
) {
  let position: GeometryPose = {
      ...poseOf(initial),
      width: 0,
      height: 0,
      ...initial,
    },
    velocity: GeometryPose = {
      x: 0,
      y: 0,
      scale: 0,
      rotation: 0,
      width: 0,
      height: 0,
    };
  let target = { ...position },
    from = { ...position },
    speed = { ...velocity },
    start = 0;
  let spring = DEFAULT_SPRING,
    frame = 0,
    safety: ReturnType<typeof setTimeout> | undefined,
    done: (() => void) | undefined,
    disposed = false;
  const paint = () =>
    painter
      ? painter(position)
      : (node.style.transform = `translate3d(${position.x}px, ${position.y}px, 0) rotate(${position.rotation}deg) scale(${position.scale})`);
  const sample = () => {
    const elapsed = (performance.now() - start) / 1000;
    for (const key of keys) {
      const value = sampleSpring(
        from[key],
        target[key],
        speed[key],
        elapsed,
        spring,
      );
      position[key] = value.position;
      velocity[key] = value.velocity;
    }
  };
  // Interrupt from the last painted frame, rather than advancing unseen geometry
  // to the event timestamp. Position and velocity already share that frame.
  const stop = () => {
    if (frame) {
      cancelAnimationFrame(frame);
      frame = 0;
    }
    clearTimeout(safety);
    done = undefined;
  };
  const finish = () => {
    cancelAnimationFrame(frame);
    frame = 0;
    clearTimeout(safety);
    position = { ...target };
    velocity = { x: 0, y: 0, scale: 0, rotation: 0, width: 0, height: 0 };
    paint();
    const callback = done;
    done = undefined;
    callback?.();
  };
  const tick = () => {
    if (disposed) return;
    sample();
    paint();
    if (
      performance.now() - start > 4000 ||
      keys.every(
        (key) =>
          Math.abs(position[key] - target[key]) <
            (key === "scale" ? 0.0001 : 0.02) &&
          Math.abs(velocity[key]) < (key === "scale" ? 0.001 : 0.1),
      )
    )
      finish();
    else frame = requestAnimationFrame(tick);
  };
  paint();
  return {
    read() {
      stop();
      return { ...position };
    },
    peek() {
      return { ...position };
    },
    set(point: Point & Partial<GeometryPose>) {
      stop();
      position = {
        ...poseOf(point),
        width: position.width,
        height: position.height,
        ...point,
      };
      target = { ...position };
      velocity = { x: 0, y: 0, scale: 0, rotation: 0, width: 0, height: 0 };
      paint();
    },
    to(
      point: Point & Partial<GeometryPose>,
      reduced: boolean,
      options: MotionOptions = {},
    ) {
      if (disposed) return;
      stop();
      target = {
        ...poseOf(point),
        width: position.width,
        height: position.height,
        ...point,
      };
      done = options.onFinish;
      if (
        reduced ||
        keys.every(
          (key) => position[key] === target[key] && velocity[key] === 0,
        )
      ) {
        finish();
        return;
      }
